const PHONE_MAX_ENTRIES = 120;
const PHONE_MAX_BYTES = 48000;
const PHONE_MIN_TURNS_BETWEEN = 3;
const PHONE_OP_ADD = 'phone.add';
const PHONE_OP_REVEAL = 'phone.reveal';
