    if (!store || typeof store !== 'object') return store;
    const ids = (Array.isArray(entryIds) ? entryIds : [entryIds]).map(phoneSafeId).filter(Boolean);
    const set = new Set(Array.isArray(store.seenIds) ? store.seenIds : []);
    for (const id of ids) {
        set.delete(id);
        set.add(id);
    }
