    const unlocked = gaNormalizePrefs(prefs).unlockedEggSkins;
    const eligible = EGG_SKINS.filter(skin => skin.rarity === rarity || (rarity === 'mythic' && skin.rarity === 'ssr'));
    const pool = eligible.length ? eligible : EGG_SKINS;
