    if (!state || state.pendingWorldEvent) return false;
    const clean = String(event ?? '').replace(/[\u0000-\u001f]/g, ' ').trim().slice(0, 200);
    const text = ctxPack({ worldEvent: clean, maxTokens }).depth0;
    if (!text) return false;
